### Tested versions

reproducible: in v4.4.1.stable.official [49a5bc7b6]
Vulkan 1.3.289 - Forward+ - Using Device #0: NVIDIA - NVIDIA GeForce RTX 4060 Laptop GPU


### System information

Windows 11 Famille, v4.4.1.stable.official [49a5bc7b6], Vulkan 1.3.289 - Forward+ - Using Device #0: NVIDIA - NVIDIA GeForce RTX 4060 Laptop GPU

### Issue description

When using `multimesh_get_buffer_rd_rid()` to write MultiMesh instance data GPU-side via `RenderingDevice`, the buffer is filled correctly (verified with `multimesh_get_buffer()`), but the instances do not render unless `multimesh_get_buffer()` and `multimesh_set_buffer()` are called explicitly. This behavior occurs consistently across both minimal and complex projects, indicating a missing synchronization between the GPU-written buffer and the `RenderingServer` for rendering. The expected behavior is that GPU-side writes should render without requiring a CPU-side sync.

This issue defeats the purpose of GPU-driven workflows, as the `get`/`set` workaround involves a GPU-to-CPU-to-GPU transfer, negating performance benefits.

### Steps to reproduce

1. Create a MultiMesh with `RenderingServer.multimesh_allocate_data(multimesh, MAX_INSTANCES, RenderingServer.MULTIMESH_TRANSFORM_3D)`.
2. Obtain the buffer RID with `RenderingServer.multimesh_get_buffer_rd_rid(multimesh)`.
3. Use a compute shader via `RenderingDevice` to write instance data (e.g., 12 floats per instance for `MULTIMESH_TRANSFORM_3D`).
4. Dispatch the compute shader and end the compute list.
5. Skip `RenderingServer.multimesh_get_buffer()` and `RenderingServer.multimesh_set_buffer()`.
6. Observe that no instances render, despite the buffer containing valid data (confirmed via `multimesh_get_buffer()`).

### Minimal reproduction project (MRP)

script : extends Node3D

const MAX_INSTANCES : int = 1000

@export var grass_mesh : Mesh

@export var tile_size : int = 1

[multimesh_issue.zip](https://github.com/user-attachments/files/19629928/multimesh_issue.zip)

6

func _ready() -> void:
	var scenario : RID = get_world_3d().scenario
	var mesh : RID = grass_mesh.get_rid()

	var rd = RenderingServer.get_rendering_device()
	var multimesh = RenderingServer.multimesh_create()
	RenderingServer.multimesh_allocate_data(multimesh, 1000, RenderingServer.MULTIMESH_TRANSFORM_3D)
	RenderingServer.multimesh_set_mesh(multimesh, mesh)
	var instance = RenderingServer.instance_create2(multimesh, scenario)
	var buffer_rid = RenderingServer.multimesh_get_buffer_rd_rid(multimesh)
	print("Buffer RID Type: ", typeof(buffer_rid)) # Doit être 23
	print("Buffer RID: ", buffer_rid)

	var shader_file := load("res://grass_compute.glsl")
	var shader_spirv: RDShaderSPIRV = shader_file.get_spirv()
	var shader := rd.shader_create_from_spirv(shader_spirv)

	var uniform := RDUniform.new()
	uniform.add_id(buffer_rid)
	uniform.uniform_type = RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER
	uniform.binding = 0 
	print("Uniform IDs: ", uniform.get_ids())
	var uniform_set := rd.uniform_set_create([uniform], shader, 0)

	var pipeline := rd.compute_pipeline_create(shader)
	var compute_list := rd.compute_list_begin()
	rd.compute_list_bind_compute_pipeline(compute_list, pipeline)
	rd.compute_list_bind_uniform_set(compute_list, uniform_set, 0)
	rd.compute_list_dispatch(compute_list, 16, 1, 1)
	rd.compute_list_end()

	print("Buffer sample: ", RenderingServer.multimesh_get_buffer(multimesh).slice(12, 24))
	#var buffer = RenderingServer.multimesh_get_buffer(multimesh)
	#RenderingServer.multimesh_set_buffer(multimesh, buffer)

grass_compute : compute shader GLSL

#[compute]
#version 450
layout(local_size_x = 16, local_size_y = 1, local_size_z = 1) in;
layout(set = 0, binding = 0, std430) buffer OutputBuffer {
    float data[];
};
void main() {
    uint idx = gl_GlobalInvocationID.x;
    if (idx >= data.length()) return;
    uint base = idx * 12; // Chaque instance occupe 12 float
        data[base + 0] = 1.0;
        data[base + 1] = 0.0;
        data[base + 2] = 0.0;
        data[base + 3] = float(idx)/2.0;
        data[base + 4] = 0.0;
        data[base + 5] = 1.0;
        data[base + 6] = 0.0;
        data[base + 7] = 0.0;
        data[base + 8] = 0.0;
        data[base + 9] = 0.0;
        data[base + 10] = 1.0;
        data[base + 11] = float(idx)/4.0;
}
